import {FLEET_BOATS,FLEET_ROUTES,FLEET_UPGRADES,LIGHTHOUSE_STAGES,LIGHTHOUSE_SECONDS,fleetEligible,berthCount,boatBlocker,voyagePlan,voyageBlocker,repeatVoyageBlocker,boatUpgradeBlocker,lighthouseBlocker,boatCargoCapacity,circuitPlan,circuitBlocker,COASTAL_PROJECTS,coastalProjectBlocker,commissionPlan,commissionBlocker} from './engine.js';

import {fleetHull} from './boat-art.js';
export {fleetHull};

export function fleetEntryView(s){return `<article class="build-card fleet-entry"><div class="panel-eyebrow">CHAPTER 06 · THE WORKING COAST</div><h3>Give your harvest a destination.</h3><p>Buy a boat, develop two coastal partnerships and restore the lighthouse. Your garden supplies voyages; your kiln supplies jars, island roofs and the headland.</p><button class="button" data-action="go-fleet">${fleetEligible(s)?'Manage the coastal fleet':'Preview the coastal fleet'}</button></article>`;}

export function lighthouseView(s,{costs,ingredients,goalTools}){
 const l=s.fleet.lighthouse;
 return `<div class="lighthouse-preview stage-${l.stage}" aria-hidden="true"></div><h2>Bring back the light.</h2><p class="description">Three visible restoration stages. Completed voyages build the partnerships needed for each. The finished lighthouse opens berth two and longer expeditions.</p><div class="lighthouse-steps">${LIGHTHOUSE_STAGES.map((p,index)=>{const current=index===l.stage,done=index<l.stage,working=current&&l.left>0,reason=current?lighthouseBlocker(s):'';return `<article class="lighthouse-step ${done?'finished':''}"><div class="panel-eyebrow">STAGE ${index+1} ${done?'· COMPLETE':working?'· CREW ON SITE':''}</div><h3>${p.name}</h3><p>${p.description}</p>${done?'<span class="success-tag">Restored</span>':working?`<div class="progress"><i data-lighthouse-bar></i></div><p data-lighthouse-time></p><p class="hint">Materials paid. The crew follows the simulation clock.</p>`:`<div class="cost">${costs(p.cost)}</div><p class="hint">Voyages required: ${p.requires.quarry} to Pietra Cove · ${p.requires.island} to Isola dei Pescatori.</p>${current?`${ingredients(Object.fromEntries(Object.entries(p.cost).filter(([k])=>k!=='coins')),'lighthouse:'+index)}${goalTools('lighthouse:'+index)}<button class="button" data-action="lighthouse-fund" data-stage="${index}" ${reason?'disabled':''}>Fund ${p.name.toLowerCase()}</button>${reason?`<p class="hint">${reason}</p>`:''}`:'<p class="hint">Complete the previous stage first.</p>'}`}</article>`;}).join('')}</div>${l.stage===3?'<button class="button" data-action="fleet-boat" data-slot="1">Choose a boat for berth two →</button>':''}`;
}

export function fleetDestinationsView(s,view){
 const {costs,ingredients,goalTools}=view;
 return `<h2>A coast that grows with you.</h2><p class="description">Invest the goods you could sell into permanent improvements. Each settlement develops independently; its benefits apply to future departures.</p>${Object.entries(FLEET_ROUTES).map(([key,r])=>{
  const stage=s.fleet.development[key],project=COASTAL_PROJECTS[key][stage],reason=coastalProjectBlocker(s,key),goal='coastal:'+key+':'+stage,commission=commissionPlan(s,key),commissionReason=commissionBlocker(s,key);
  return `<article class="destination-card"><div class="panel-eyebrow">${key==='quarry'?'CONSTRUCTION MATERIALS':'COASTAL COMMERCE'}</div><h3>${r.name}</h3><p>${r.description}</p><div class="partnership-progress"><strong>${s.fleet.visits[key]} completed voyages · ${stage} / 3 projects</strong><span>${s.fleet.visits[key]>=3?'Partnership established':Math.max(0,3-s.fleet.visits[key])+' voyages to partnership'}</span></div><ol class="coastal-project-track">${COASTAL_PROJECTS[key].map((p,i)=>`<li class="${i<stage?'complete':i===stage?'current':''}"><span>${i<stage?'✓':i+1}</span><div><strong>${p.name}</strong><small>${p.description}</small></div></li>`).join('')}</ol>${project?`<div class="coastal-funding"><div class="panel-eyebrow">NEXT PROJECT · ${project.visits} VOYAGES REQUIRED</div><h3>${project.name}</h3><div class="cost">${costs(project.cost)}</div>${ingredients(Object.fromEntries(Object.entries(project.cost).filter(([k])=>k!=='coins')),goal)}${goalTools(goal)}<button class="button" data-action="coastal-fund" data-key="${key}" data-stage="${stage}" ${reason?'disabled':''}>Fund ${project.name.toLowerCase()}</button><p class="hint">${reason||'Materials and funds are spent once. The improvement opens immediately.'}</p></div>`:`<div class="coastal-funding"><div class="panel-eyebrow">WORKING PARTNERSHIP · ORDER ${s.fleet.commissions[key]+1}</div><h3>${commission.name}</h3><p class="hint">A rotating dock commission. Fulfil it directly from town stock; it does not occupy a boat.</p>${ingredients(commission.cost,commission.goal)}${goalTools(commission.goal)}<div class="reward"><span>In return</span><strong>${costs(commission.reward)}</strong></div><button class="button" data-action="commission-complete" data-key="${key}" data-count="${commission.count}" ${commissionReason?'disabled':''}>Deliver commission</button>${commissionReason?`<p class="hint">${commissionReason}</p>`:''}</div>`}<div class="route-unlocks">${r.tiers.map((t,i)=>`<div class="route-unlock"><strong>${t.name}</strong><small>${s.fleet.visits[key]<t.visits?t.visits+' visits required':t.lighthouse&&s.fleet.lighthouse.stage<3?'Restore the lighthouse':'Available'} · ${i===2?'longer voyage, larger cargo':i===1?'same cargo, better return':'short supply voyage'}</small></div>`).join('')}</div><button class="button secondary" data-action="fleet-destination" data-key="${key}">Plan a voyage here</button></article>`;
 }).join('')}`;
}

function cargoMeter(used,capacity,circuit=false){return `<div class="cargo-capacity ${used>capacity?'over-capacity':''}"><div><strong>Cargo hold</strong><span>${used} / ${capacity} units</span></div><meter min="0" max="${capacity}" value="${Math.min(used,capacity)}" aria-label="Cargo hold: ${used} of ${capacity} units"></meter><p class="hint">${used>capacity?'Too much cargo. Choose a smaller contract or expand your hold.':circuit?'Every item occupies one unit. Goods for both stops must fit before departure.':'Every item occupies one unit of your cargo hold.'}</p></div>`;}
function circuitPlanner(s,slot,stops,view){
 const {costs,ingredients,goalTools}=view,plan=circuitPlan(s,slot,stops),reason=circuitBlocker(s,slot,stops);
 return `<div class="circuit-intro"><h3>One departure. Two destinations.</h3><p>Load both contracts before leaving. Your boat visits Pietra Cove, then Isola dei Pescatori, and brings all rewards home together. A circuit takes 20% less time than the two separate trips.</p><p class="hint">For circuits, the cargo upgrade adds hold capacity so you can select larger contracts. It does not automatically increase each stop’s cargo.</p></div>${stops.map((stop,index)=>`<fieldset class="circuit-stop"><legend>${index+1}. ${FLEET_ROUTES[stop.route].name}</legend><div class="fleet-contracts">${FLEET_ROUTES[stop.route].tiers.map((t,i)=>`<button data-action="circuit-tier" data-slot="${slot}" data-key="${stop.route}" data-tier="${i+1}" aria-pressed="${stop.tier===i+1}">${t.name}<small>${s.fleet.visits[stop.route]<t.visits?t.visits+' visits needed':t.lighthouse&&s.fleet.lighthouse.stage<3?'Lighthouse needed':'Available'}</small></button>`).join('')}</div></fieldset>`).join('')}${plan?`<article class="voyage-card"><h3>${plan.name}</h3><p class="hint">${plan.duration} simulation seconds · ${stateSpeedNote(s)}</p>${cargoMeter(plan.used,plan.capacity,true)}${ingredients(plan.cost,plan.goal)}${goalTools(plan.goal)}<div class="reward"><span>Combined return</span><strong>${costs(plan.reward)}</strong></div><button class="button" data-action="circuit-depart" data-slot="${slot}" ${reason?'disabled':''}>Load two stops & sail</button>${reason?`<p class="hint">${reason}</p>`:''}</article>`:`<p class="hint">${reason||'Choose two contracts to plan this voyage.'}</p>`}`;
}

export function fleetPanelView(s,ui,view){
 const {costs,ingredients,goalTools}=view,slot=ui.slot===1?1:0,b=s.fleet.boats[slot],selection=ui.selections[slot],section=ui.section,mode=ui.modes?.[slot]||'single',stops=ui.circuits?.[slot]||[{route:'quarry',tier:1},{route:'island',tier:1}];
 let html=`<div class="panel-eyebrow">CHAPTER 06 · THE WORKING COAST</div><h2>A fleet with a purpose.</h2><p class="description">Send your harvest to the coast. Choose materials or earnings, develop partnerships and rebuild the lighthouse.</p><button class="text-button" data-action="district" data-key="coast">Explore the coast →</button>`;
 if(!fleetEligible(s))return html+`<article class="build-card"><h3>First, establish inland trade</h3><p>Complete your first preserves shipment to Valle Serena. Then you can buy a boat and supply the coastal settlements.</p><button class="button" data-action="go-inland">Continue the inland chain</button></article>`;
 html+=`<div class="fleet-navigation" aria-label="Fleet sections">${[['voyages','Boats & cargo'],['destinations','Destinations'],['lighthouse','Lighthouse']].map(([key,label])=>`<button data-action="fleet-view" data-key="${key}" aria-pressed="${section===key}">${label}</button>`).join('')}</div>`;
 if(section==='lighthouse')return html+lighthouseView(s,view);
 if(section==='destinations')return html+fleetDestinationsView(s,view);
 html+=`<div class="berth-selector">${s.fleet.boats.map((boat,i)=>`<button data-action="fleet-boat" data-slot="${i}" aria-pressed="${slot===i}"><strong>Berth ${i+1}</strong><small>${i>=berthCount(s)?'Lighthouse needed':boat?FLEET_BOATS[boat.type].name:'Choose a boat'}${boat?.trip?' · at sea':''}</small></button>`).join('')}</div>`;
 if(slot>=berthCount(s))return html+'<article class="build-card"><h3>A second working berth</h3><p>Restore all three lighthouse stages to buy a second vessel and run two routes together.</p><button class="button" data-action="fleet-view" data-key="lighthouse">Plan lighthouse restoration</button></article>';
 if(!b)return html+`<p class="description">Choose this berth’s vessel. Boats cannot currently be sold or exchanged; choose the role that fits your production.</p>${Object.entries(FLEET_BOATS).map(([type,d])=>{const reason=boatBlocker(s,slot,type);return `<article class="boat-choice">${fleetHull(type)}<h3>${d.name}</h3><p>${d.description}</p><p class="hint">${type==='cutter'?'Quarry supply: 4 preserves, 4 bread, 2 jars · 30s':'Quarry supply: 8 preserves, 8 bread, 4 jars · 50s'}</p><div class="cost">${costs(d.cost)}</div><button class="button" data-action="fleet-buy" data-slot="${slot}" data-key="${type}" ${reason?'disabled':''}>Buy ${d.name.toLowerCase()}</button>${reason?`<p class="hint">${reason}</p>`:''}</article>`;}).join('')}`;
 html+=`<div class="boat-summary">${fleetHull(b.type)}<div><h3>${FLEET_BOATS[b.type].name}</h3><p>${b.upgrade?FLEET_UPGRADES[b.upgrade].name:'Standard setup'} · ${b.trip?'At sea':'In harbour'} · ${boatCargoCapacity(s,slot)} cargo units</p></div></div>`;
 if(b.trip){const t=b.trip;html+=`<article class="voyage-card"><div class="panel-eyebrow">${t.ferry?'PASSENGER SERVICE':'CARGO COMMITTED'}</div><h3>${t.stops?'Two-stop coastal circuit':FLEET_ROUTES[t.route].name}</h3><p>${t.ferry?'Passenger service':t.stops?t.stops.map(p=>FLEET_ROUTES[p.route].name+' · '+FLEET_ROUTES[p.route].tiers[p.tier-1].name).join(' → '):FLEET_ROUTES[t.route].tiers[t.tier-1].name}</p><div class="progress"><i data-voyage-bar="${slot}"></i></div><p data-voyage-time="${slot}"></p><p class="hint">Loaded: ${costs(t.cargo)}</p><div class="reward"><span>On return</span><strong>${costs(t.reward)}</strong></div><p class="hint">Rewards arrive once, when the boat returns. Closing the game pauses this voyage.</p><button class="button secondary" data-action="fleet-recall" data-slot="${slot}">Recall & return cargo</button><p class="hint">Recall refunds the loaded goods, earns no reward or visit, and stops repeat trips.</p></article>`;}
 else{
  html+=`<div class="fleet-mode" aria-label="Voyage type"><button data-action="fleet-mode" data-slot="${slot}" data-key="single" aria-pressed="${mode==='single'}">Single destination</button><button data-action="fleet-mode" data-slot="${slot}" data-key="circuit" aria-pressed="${mode==='circuit'}">Two-stop circuit</button></div>`;
  if(mode==='circuit')html+=circuitPlanner(s,slot,stops,view);
  else{
  const plan=voyagePlan(s,slot,selection.route,selection.tier),reason=voyageBlocker(s,slot,selection.route,selection.tier);
  html+=`<div class="fleet-routes">${Object.entries(FLEET_ROUTES).map(([key,r])=>`<button data-action="fleet-route" data-slot="${slot}" data-key="${key}" aria-pressed="${selection.route===key}">${r.name}<small>${s.fleet.visits[key]} voyages completed</small></button>`).join('')}</div><div class="fleet-contracts">${FLEET_ROUTES[selection.route].tiers.map((t,index)=>`<button data-action="fleet-tier" data-slot="${slot}" data-tier="${index+1}" aria-pressed="${selection.tier===index+1}">${t.name}<small>${s.fleet.visits[selection.route]<t.visits?t.visits+' visits needed':t.lighthouse&&s.fleet.lighthouse.stage<3?'Lighthouse needed':'Available'}</small></button>`).join('')}</div>`;
  if(plan)html+=`<article class="voyage-card"><h3>${plan.name}</h3><p class="hint">${plan.duration} simulation seconds · ${stateSpeedNote(s)}</p>${cargoMeter(Object.values(plan.cost).reduce((sum,n)=>sum+n,0),boatCargoCapacity(s,slot))}${ingredients(plan.cost,plan.goal)}${goalTools(plan.goal)}<div class="reward"><span>On return</span><strong>${costs(plan.reward)}</strong></div><button class="button" data-action="fleet-depart" data-slot="${slot}" data-key="${selection.route}" data-tier="${selection.tier}" ${reason?'disabled':''}>Load & sail</button>${reason?`<p class="hint">${reason}</p>`:''}</article>`;
  else html+=`<p class="hint">${reason||'Choose an available route.'}</p>`;
  }
 }
 const route=b.trip?.route||selection.route,tier=b.trip?.tier||selection.tier,repeatReason=repeatVoyageBlocker(s,slot,route,tier);
 if(!b.trip?.ferry&&!b.trip?.stops&&mode!=='circuit')html+=`<article class="repeat-card"><strong>Repeat voyages</strong><p>${b.repeat?'Enabled · '+FLEET_ROUTES[b.repeat.route].name+' · '+FLEET_ROUTES[b.repeat.route].tiers[b.repeat.tier-1].name:'Off. You decide when to sail.'}</p><button class="button secondary" data-action="fleet-repeat" data-slot="${slot}" data-key="${route}" data-tier="${tier}" data-on="${!b.repeat}" ${!b.repeat&&repeatReason?'disabled':''}>${b.repeat?'Stop repeat trips':'Enable repeat trips'}</button><p class="hint">${b.repeat?'The next voyage waits for sufficient unreserved cargo. Stopping repeat leaves a current voyage running.':repeatReason||'Reuses this contract while cargo is available. It spends unreserved goods each departure; it does not start production.'}</p></article>`;
 else html+=`<p class="hint">${b.trip?.ferry?'Passenger services are dispatched manually and stop cargo repeats.':'Two-stop circuits are dispatched manually. Existing repeat voyages are stopped when a circuit departs.'}</p>`;
 html+=`<details class="fleet-upgrades"><summary>Compare boat upgrades</summary><p class="hint">Choose speed or cargo. Replacing an upgrade costs the full price, gives no refund and requires the boat to be idle. Loaded cargo is never changed.</p>${Object.entries(FLEET_UPGRADES).map(([mode,d])=>{const why=boatUpgradeBlocker(s,slot,mode);return `<article class="boat-upgrade"><h3>${d.name}</h3><p>${d.description}</p><div class="cost">${costs(d.cost)}</div><button class="button secondary" data-action="fleet-upgrade" data-slot="${slot}" data-key="${mode}" ${why?'disabled':''}>${b.upgrade===mode?'Installed':'Install '+d.name.toLowerCase()}</button>${why?`<p class="hint">${why}</p>`:''}</article>`;}).join('')}</details><button class="text-button" data-action="fleet-view" data-key="lighthouse">Lighthouse: ${s.fleet.lighthouse.stage} / 3 stages restored →</button>`;
 return html;
}
function stateSpeedNote(s){return s.speed===0?'town paused':s.speed===3?'3× speed selected':'1× speed selected';}
